def P(t,style='BodyA'): return Paragraph(str(t).replace('&','&amp;'),styles[style])
def score_color(s): return GREEN if s>=8 else AMBER if s>=5 else RED
def score_status(s): return 'Strong' if s>=8 else 'On Track' if s>=5 else 'Needs Work'

def base_table(data,widths=None,header=True,fontsize=7.5):
    converted=[]
    for ri,r in enumerate(data):
        converted.append([x if hasattr(x,'wrap') else P(x,'TableHeadA' if header and ri==0 else 'SmallA') for x in r])
    t=Table(converted,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmd=[('GRID',(0,0),(-1,-1),0.35,BORDER),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]
    if header: cmd += [('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),WHITE)]
    for i in range(1 if header else 0,len(data)):
        if i%2==0: cmd.append(('BACKGROUND',(0,i),(-1,i),LIGHT))
    t.setStyle(TableStyle(cmd)); return t

